const W={fist:['Fäuste',5,1,0],knife:['Messer',9,1,75],pistol:['Colt M1911',14,3,220],shotgun:['Schrotflinte',19,2,390],tommy:['Thompson-MP',25,4,650]},C={none:['Zu Fuß',8,0],ford:['Ford Model A',12,480],buick:['Buick Sedan',15,900],cadillac:['Cadillac V8',18,1600]},R=[[0,'Niemand'],[10,'Anfänger'],[25,'Kleiner Fisch'],[45,'Ganove'],[65,'Mafioso'],[85,'Pate'],[100,'Chef der Unterwelt']],N=['Vinnie Moretti','Frankie Russo','Sal Vitale','Lola Marino','Tony Bellini','Nina Caruso','Eddie Malone','Rocco Bianchi'];
const fresh=()=>({v:2,m:1,y:1925,cash:450,score:0,heat:0,steps:8,max:8,loc:'hideout',hotel:0,car:'none',debt:0,loan:false,invest:0,booze:0,fake:0,passport:false,shops:0,stock:{knife:0,pistol:0,shotgun:0,tommy:0},crew:[{id:1,name:'Du',skill:42,power:45,intel:40,hp:100,weapon:'fist',jailed:false}],mayorTip:false,transportTip:false,mayorDone:false,transportDone:false,train:false,over:false,rivals:[['Familie Romano',35,3],['O’Connor Gang',28,2],['North Side Mob',45,4]],log:['Januar 1925: Du wirst aus dem Gefängnis entlassen.']});
let prior=null;try{prior=JSON.parse(localStorage.getItem('uw1931')||'null')}catch(e){localStorage.setItem('uw1931-damaged',localStorage.getItem('uw1931')||'')}let S=prior?.v===2?prior:fresh(),selected=S.loc,deferred,fight;
const month=()=>['','Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'][S.m],crew=()=>S.crew.filter(x=>!x.jailed),rankName=()=>[...R].reverse().find(x=>S.score>=x[0])[1];
function save(){localStorage.setItem('uw1931',JSON.stringify(S));render()}function note(t){S.log.unshift(`${month()} ${S.y}: ${t}`);S.log=S.log.slice(0,60)}function toast(t){let x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}function pay(n){if(S.cash<n){toast('Nicht genug Bargeld.');return false}S.cash-=n;return true}function chance(n){return Math.random()<Math.max(.08,Math.min(.92,n+crew().reduce((a,c)=>a+c.skill,0)/1200-S.heat/280))}
function render(){$('#date').textContent=`${month().toUpperCase()} ${S.y}`;$('#cash').textContent=cash(S.cash);$('#rank').textContent=rankName();$('#heat').textContent=S.heat+'%';$('#crewCount').textContent=crew().length+'/'+S.crew.length;$('#steps').textContent=S.steps;$('#location').textContent=B[S.loc][0];drawMap();drawPanel();if(S.over&&!modal.open)endScreen()}
function drawMap(){map.querySelectorAll('.place').forEach(e=>e.remove());Object.entries(B).forEach(([k,b])=>{if(k==='mayor'&&!S.mayorTip||k==='transport'&&!S.transportTip)return;let x=document.createElement('button');x.className='place'+(k===selected?' active':'')+(['mayor','transport'].includes(k)?' special':'');x.style.cssText=`--x:${b[3]}%;--y:${b[4]}%`;x.innerHTML=`<span>${b[1]}</span>${b[0]}<small>${b[2]}</small>`;x.onclick=()=>visit(k);map.append(x)})}
function visit(k){if(k!==S.loc){if(!S.steps)return toast('Keine Schritte mehr.');S.steps--;S.loc=selected=k;policeCheck()}else selected=k;save()}
