function options(k){return({hideout:[bt('Bande erholen','rest'),bt('Karriere','career')],pub:[bt('Gangster anwerben','hire',S.hotel?'ab $180':'Hotel nötig'),bt('Kleiner Auftrag','job','$70–160'),bt('Alkohol kaufen','booze','$80'),bt('Alkohol verkaufen','sell'),bt('Wirt ausfragen','tip')],hotel:[bt('Billiges Zimmer','hotel1','$100/Monat'),bt('Gutes Hotel','hotel2','$250/Monat'),bt('Luxussuite','hotel3','$500/Monat')],weapons:[bt('Waffen kaufen','weapons'),bt('Bande ausrüsten','equip'),bt('Training','train','$120')],cars:[bt('Auto kaufen','cars'),bt('Auto stehlen','steal')],shop:[bt('Betteln','beg'),bt('Kasse stehlen','robshop'),bt('Schutzgeld','protect','ab Ganove')],bank:[bt('Banküberfall','bank'),bt('Tresor knacken','safe','Intelligenz 55')],casino:[bt('Blackjack','blackjack')],fake:[bt('Blüten kaufen','fake','$100 → $160'),bt('Neuen Pass','passport','$500')],subway:[bt('Taschendiebstahl','pick')],police:[bt('Polizeichef bestechen','bribe','$150'),bt('Gangster befreien','breakout')],loan:[bt('Kredit aufnehmen','borrow','$1.000'),bt('Geschäft kaufen','buyloan','$5.000'),bt('Investieren','invest'),bt('Schulden eintreiben','collect')],station:[bt('Taschendiebstahl','pick'),bt('Alkohol kaufen','booze','$65'),bt('Postzug überfallen','posttrain')],mayor:[bt('Auftrag beginnen','mayorfight')],transport:[bt('Transport stoppen','transportfight')]}[k]||[]).join('')}
function drawPanel(){let b=B[selected];panel.innerHTML=`<span class="eyebrow">${b[2]}</span><h2>${b[0]}</h2><p>${b[5]}</p><div class="actions">${options(selected)}</div><div class="hint">Reisen kostet Schritte. Am Monatsende werden sie aufgefüllt.</div>`;panel.querySelectorAll('[data-act]').forEach(x=>x.onclick=()=>action(x.dataset.act))}
function reward(n,p,h,msg){S.cash+=n;S.score=Math.min(100,S.score+p);S.heat=Math.min(100,S.heat+h);note(msg);toast(msg+' · '+cash(n));save()}function crime(p,a,b,s,h,msg,battle=false){if(chance(p)){if(battle&&Math.random()<.35)return beginFight('Bewaffnete Gegner',2,()=>reward(rnd(a,b),s,h,msg));reward(rnd(a,b),s,h,msg)}else fail()}function fail(){S.heat=Math.min(100,S.heat+12);if(Math.random()<.3)arrest();note('Ein Verbrechen scheiterte.');toast('Gescheitert – Polizei alarmiert.');save()}
function action(a){if(a==='rest'){S.crew.forEach(x=>x.hp=Math.min(100,x.hp+35));toast('Bande erholt.');save()}if(a==='career')career();if(a==='hire')hire();if(a==='job')crime(.78,70,160,2,5,'Auftrag erledigt');if(a==='booze'){let p=selected==='station'?65:80;if(pay(p)){S.booze++;toast('Alkoholfass gekauft.');save()}}if(a==='sell'){if(!S.booze)return toast('Kein Alkohol vorhanden.');S.booze--;reward(rnd(100,190),1,2,'Alkohol verkauft')}if(a==='tip')tip();if(a.startsWith('hotel')){S.hotel=+a.at(-1);toast('Unterkunft gewählt.');save()}if(a==='weapons')weaponShop();if(a==='equip')equip();if(a==='train')training();if(a==='cars')carShop();if(a==='steal')stealCar();if(a==='beg')crime(.9,8,28,0,1,'Geld erbettelt');if(a==='robshop')crime(.63,45,130,2,9,'Kasse ausgeräumt',true);if(a==='protect')protect();if(a==='bank')bank(false);if(a==='safe')bank(true);if(a==='blackjack')blackjack();if(a==='fake'&&pay(100)){S.fake+=160;S.heat=Math.min(100,S.heat+3);toast('$160 Blüten gekauft.');save()}if(a==='passport'&&pay(500)){S.passport=true;S.heat=Math.max(0,S.heat-35);toast('Neue Identität.');save()}if(a==='pick')crime(.75,20,100,1,4,'Taschendiebstahl gelungen');if(a==='bribe'&&pay(150)){S.heat=Math.max(0,S.heat-30);toast('Polizeichef bestochen.');save()}if(a==='breakout')breakout();if(a==='borrow'){S.cash+=1000;S.debt+=1300;toast('$1.000 Kredit aufgenommen.');save()}if(a==='buyloan')buyLoan();if(a==='invest')invest();if(a==='collect')collect();if(a==='posttrain')postTrain();if(a==='mayorfight')beginFight('Leibwächter',5,()=>{S.mayorDone=true;S.mayorTip=false;reward(1200,15,25,'Bürgermeister-Auftrag erfüllt')});if(a==='transportfight')beginFight('Polizeieskorte',7,()=>{S.transportDone=true;S.transportTip=false;reward(2500,18,35,'Geldtransport erbeutet')})}
function hire(){if(!S.hotel)return toast('Zuerst Hotelzimmer mieten.');let list=Array.from({length:2+S.hotel},(_,i)=>({name:N[(S.m+i+S.crew.length)%N.length],skill:rnd(30,55+S.hotel*8),power:rnd(25,70),intel:rnd(25,70),price:180+S.hotel*70+i*35}));show('Gangster anwerben',`<div class="list">${list.map(c=>`<div class="item"><div class="item-head"><b>${c.name}</b><b>${cash(c.price)}</b></div><span>Geschick ${c.skill} · Kraft ${c.power} · Intelligenz ${c.intel}</span><button data-hire='${JSON.stringify(c)}'>Anheuern</button></div>`).join('')}</div>`);modalBody.querySelectorAll('[data-hire]').forEach(x=>x.onclick=()=>{let c=JSON.parse(x.dataset.hire);if(!pay(c.price))return;Object.assign(c,{id:Date.now(),hp:100,weapon:'fist',jailed:false});S.crew.push(c);note(c.name+' angeheuert.');save();modal.close()})}
function weaponShop(){show('Waffenhändler',`<div class="list">${Object.entries(W).filter(x=>x[0]!=='fist').map(([k,w])=>`<div class="item"><b>${w[0]} · ${cash(w[3])}</b><span>Schaden ${w[1]} · Reichweite ${w[2]}</span><button data-w="${k}">Kaufen</button></div>`).join('')}</div>`);modalBody.querySelectorAll('[data-w]').forEach(x=>x.onclick=()=>{let w=W[x.dataset.w];if(pay(w[3])){S.stock[x.dataset.w]++;save();toast(w[0]+' gekauft.')}})}
function equip(){show('Ausrüsten',`<div class="list">${crew().map(c=>`<div class="item"><b>${c.name}</b><span>${W[c.weapon][0]}</span>${Object.entries(S.stock).filter(x=>x[1]>0).map(([k,n])=>`<button data-e="${c.id}|${k}">${W[k][0]} (${n})</button>`).join('')}</div>`).join('')}</div>`);modalBody.querySelectorAll('[data-e]').forEach(x=>x.onclick=()=>{let[id,w]=x.dataset.e.split('|'),c=S.crew.find(y=>y.id==id);if(c.weapon!=='fist')S.stock[c.weapon]++;S.stock[w]--;c.weapon=w;save();modal.close()})}function training(){let c=crew().sort((a,b)=>a.skill-b.skill)[0];if(c&&pay(120)){c.skill=Math.min(95,c.skill+6);c.power=Math.min(95,c.power+4);toast(c.name+' trainiert.');save()}}
function carShop(){show('Autohändler',`<div class="list">${Object.entries(C).filter(x=>x[0]!=='none').map(([k,c])=>`<div class="item"><b>${c[0]} · ${cash(c[2])}</b><span>${c[1]} Schritte</span><button data-c="${k}">Kaufen</button></div>`).join('')}</div>`);modalBody.querySelectorAll('[data-c]').forEach(x=>x.onclick=()=>{let c=C[x.dataset.c];if(pay(c[2])){S.car=x.dataset.c;S.max=c[1];S.steps=Math.max(S.steps,c[1]);save();modal.close()}})}function stealCar(){if(chance(.48)){S.car=Math.random()<.25?'buick':'ford';S.max=C[S.car][1];reward(0,3,18,C[S.car][0]+' gestohlen')}else fail()}
function protect(){if(S.score<45)return toast('Rang Ganove erforderlich.');if(chance(.55)){S.shops++;reward(120,4,14,'Schutzgeld erpresst')}else beginFight('Ladenbesitzer',3,()=>{S.shops++;reward(80,3,18,'Laden unter Schutz')})}function bank(safe){if(S.score<25)return toast('Rang Kleiner Fisch erforderlich.');if(safe&&Math.max(...crew().map(x=>x.intel))<55)return toast('Tresorknacker benötigt.');beginFight(safe?'Tresorwachen':'Bankwachen',safe?5:4,()=>reward(safe?rnd(900,1700):rnd(450,900),safe?9:6,safe?25:18,safe?'Tresor geknackt':'Bank überfallen'))}
function blackjack(){show('Blackjack',`<p>Einsatz wählen:</p><div class="grid2">${[25,50,100,250].map(n=>`<button class="choice" data-bet="${n}">${cash(n)}</button>`).join('')}</div>`);modalBody.querySelectorAll('[data-bet]').forEach(x=>x.onclick=()=>{let n=+x.dataset.bet;if(!pay(n))return;let p=rnd(16,23),d=rnd(16,23),win=p<=21&&(d>21||p>d);if(win)S.cash+=n*2;save();modalBody.innerHTML=`<div class="item"><h3>${win?'Gewonnen':'Verloren'}</h3><span>Du ${p} · Bank ${d}</span></div>`})}
function breakout(){let j=S.crew.find(x=>x.jailed);if(!j)return toast('Niemand sitzt ein.');if(chance(.45)){j.jailed=false;S.heat+=20;toast(j.name+' befreit.');save()}else beginFight('Polizeiwache',5,()=>{j.jailed=false;reward(0,5,28,j.name+' befreit')})}function buyLoan(){if(S.loan)return toast('Geschäft gehört dir.');if(pay(5000)){S.loan=true;toast('Kreditgeschäft gekauft.');save()}}function invest(){if(!S.loan)return toast('Kreditgeschäft zuerst kaufen.');let n=Math.min(1000,5000-S.invest);if(n>0&&pay(n)){S.invest+=n;toast(cash(n)+' investiert.');save()}}function collect(){if(!S.loan)return toast('Kein Kreditgeschäft.');if(Math.random()<.45)beginFight('Schuldner',2,()=>reward(rnd(250,550),2,6,'Schulden eingetrieben'));else reward(rnd(120,350),1,2,'Schulden eingetrieben')}
function tip(){let r=Math.random();if(!S.mayorDone&&r<.35){S.mayorTip=true;toast('Bürgermeister-Auftrag entdeckt.')}else if(!S.transportDone&&r<.7){S.transportTip=true;toast('Geldtransport gesichtet.')}else{S.train=true;toast('Postzug angekündigt.')}save()}function postTrain(){if(!S.train&&Math.random()>.3)return toast('Kein lohnender Postzug.');S.train=false;beginFight('Postzug-Eskorte',5,()=>reward(rnd(700,1300),8,22,'Postzug ausgeraubt'))}
function policeCheck(){if(Math.random()>S.heat/220)return;let n=100+S.heat*2;show('Polizeikontrolle',`<div class="grid2"><button class="choice" id="br">Bestechen ${cash(n)}</button><button class="choice" id="fl">Fliehen</button><button class="choice" id="yi">Stellen</button></div>`);br.onclick=()=>{if(pay(n)){S.heat=Math.max(0,S.heat-15);save();modal.close()}};fl.onclick=()=>{modal.close();if(!chance(.48))arrest();save()};yi.onclick=()=>{modal.close();arrest();save()}}function arrest(){let c=crew().at(-1);if(c){c.jailed=true;S.heat=Math.max(10,S.heat-25);note(c.name+' verhaftet.');toast(c.name+' verhaftet!')}}
function beginFight(name,num,win){if(!crew().length)return toast('Keine kampffähige Bande.');fight={name,enemies:Array.from({length:num},(_,i)=>({name:'Gegner '+(i+1),hp:rnd(35,65),damage:rnd(7,14)})),range:3,log:['Der Kampf beginnt.'],win};drawFight();battle.showModal()}function drawFight(){let us=crew().filter(x=>x.hp>0),en=fight.enemies.filter(x=>x.hp>0);battleTitle.textContent=fight.name;battleBody.innerHTML=`<div class="battlefield"><div class="fighters">${us.map(x=>`<div class="fighter"><b>${x.name}</b><span>${W[x.weapon][0]} · ${x.hp} LP</span><div class="meter"><i style="width:${x.hp}%"></i></div></div>`).join('')}</div><div class="versus">VS</div><div class="fighters">${en.map(x=>`<div class="fighter"><b>${x.name}</b><span>${x.hp} LP</span><div class="meter"><i style="width:${x.hp}%"></i></div></div>`).join('')}</div></div><div class="battle-actions"><button data-f="attack">Angreifen</button><button data-f="advance">Vorrücken</button><button data-f="run">Fliehen</button></div><div class="log">${fight.log.slice(-7).join('<br>')}</div>`;battleBody.querySelectorAll('[data-f]').forEach(x=>x.onclick=()=>fightTurn(x.dataset.f))}
function fightTurn(a){let us=crew().filter(x=>x.hp>0),en=fight.enemies.filter(x=>x.hp>0);if(a==='run'){S.heat+=8;battle.close();return save()}if(a==='advance'){fight.range=Math.max(1,fight.range-1);fight.log.push('Bande rückt vor.')}else us.forEach(c=>{let t=en.find(x=>x.hp>0),w=W[c.weapon];if(t&&(w[2]>=fight.range&&Math.random()<.55+c.skill/220)){let d=rnd(Math.ceil(w[1]*.65),w[1]);t.hp-=d;fight.log.push(`${c.name} trifft für ${d}.`)}else fight.log.push(`${c.name} verfehlt.`)});en=fight.enemies.filter(x=>x.hp>0);if(!en.length){battle.close();return fight.win()}en.forEach(e=>{let t=us.find(x=>x.hp>0);if(t&&Math.random()<.62){let d=rnd(4,e.damage);t.hp=Math.max(0,t.hp-d);fight.log.push(`${t.name} verliert ${d} LP.`)}});if(!crew().some(x=>x.hp>0)){battle.close();S.cash=Math.max(0,S.cash-200);S.crew.forEach(x=>{if(!x.hp){x.hp=20;x.jailed=Math.random()<.5}});note('Im Kampf besiegt.');toast('Niederlage – $200 verloren.');return save()}drawFight();save()}
function nextMonth(){let wage=Math.max(0,S.crew.length-1)*60,hotel=[0,100,250,500][S.hotel],income=S.shops*90+Math.floor(S.invest*.08);S.cash+=income-wage-hotel;if(S.debt)S.debt+=Math.ceil(S.debt*.08);if(S.cash<0){S.debt-=S.cash;S.cash=0}S.crew.forEach(x=>x.hp=Math.min(100,x.hp+15));S.heat=Math.max(0,S.heat-7);if(++S.m===13){S.m=1;S.y++}S.steps=S.max=C[S.car][1];note(`Abrechnung: ${cash(income)} Einnahmen, ${cash(wage+hotel)} Kosten.`);if(S.score>=100&&S.mayorDone&&S.transportDone)S.over='win';else if(S.y>=1928)S.over='lose';save();toast('Neuer Monat · '+cash(income)+' Einnahmen')}
function show(t,h){modalTitle.textContent=t;modalBody.innerHTML=h;modal.showModal()}function career(){show('Karriere',`<div class="item"><div class="item-head"><b>${rankName()}</b><b>${S.score}/100</b></div><div class="meter"><i style="width:${S.score}%"></i></div><span>Sieg: 100 Punkte plus Bürgermeister und Geldtransport.</span></div>`)}function tab(t){if(t==='crew')show('Deine Bande',`<div class="list">${S.crew.map(c=>`<div class="item"><div class="item-head"><b>${c.name}</b><span class="badge ${c.jailed?'bad':'good'}">${c.jailed?'Gefängnis':'Bereit'}</span></div><span>${W[c.weapon][0]} · ${c.hp} LP · Geschick ${c.skill} · Kraft ${c.power} · Intelligenz ${c.intel}</span><div class="meter"><i style="width:${c.hp}%"></i></div></div>`).join('')}</div>`);if(t==='inventory')show('Besitz & Finanzen',`<div class="list"><div class="item"><b>${C[S.car][0]}</b><span>${S.max} Schritte</span></div><div class="item"><b>Vorräte</b><span>${S.booze} Fässer · ${cash(S.fake)} Blüten · ${S.passport?'neuer Pass':'alter Pass'}</span></div><div class="item"><b>Geschäfte</b><span>${S.shops} Schutzgeldzahler · Kreditgeschäft ${S.loan?'gekauft':'nicht gekauft'} · ${cash(S.invest)} investiert</span></div><div class="item"><b>Schulden ${cash(S.debt)}</b></div></div>`);if(t==='families')show('Rivalisierende Familien',`<div class="list">${S.rivals.map((r,i)=>`<div class="item"><b>${r[0]}</b><span>Stärke ${r[1]} · ${r[2]} Reviere</span><button data-war="${i}">Bandenkrieg</button></div>`).join('')}</div>`);if(t==='journal')show('Chronik',`<div class="list">${S.log.map(x=>`<div class="item"><span>${x}</span></div>`).join('')}</div>`);modalBody.querySelectorAll('[data-war]').forEach(x=>x.onclick=()=>{let r=S.rivals[+x.dataset.war];modal.close();beginFight(r[0],Math.max(2,Math.ceil(r[1]/12)),()=>{r[1]=Math.max(5,r[1]-10);r[2]=Math.max(0,r[2]-1);S.shops++;reward(400,6,20,'Bandenkrieg gewonnen')})})}
function endScreen(){let w=S.over==='win';show(w?'Chef der Unterwelt!':'Zeit abgelaufen',`<div class="item"><h3>${w?'Chicago gehört dir.':'Januar 1928'}</h3><span>${w?'Beide Spezialaufträge und höchster Rang erreicht.':`${rankName()} · ${S.score} Punkte`}</span><button id="newGame">Neues Spiel</button></div>`);newGame.onclick=()=>{S=fresh();save();modal.close()}}
document.addEventListener('click',e=>{let x=e.target.closest('[data-open]');if(x)x.dataset.open==='career'?career():tab(x.dataset.open==='crew'?'crew':'inventory')});document.querySelectorAll('nav button').forEach(x=>x.onclick=()=>{document.querySelectorAll('nav button').forEach(y=>y.classList.remove('selected'));x.classList.add('selected');if(x.dataset.tab!=='city')tab(x.dataset.tab)});$('.close').onclick=()=>modal.close();$('#endTurn').onclick=nextMonth;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;install.hidden=false});install.onclick=async()=>{if(deferred){deferred.prompt();await deferred.userChoice;deferred=null;install.hidden=true}};if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');
